import { ChangeDetectorRef, Component, OnInit } from '@angular/core';
import { InputComponent } from '../../../../shared/components/input/input.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatDialogRef } from '@angular/material/dialog';
import { HelpcenterService } from '../../../../shared/services/helpcenter/helpcenter.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { CommonModule } from '@angular/common';
import { environment } from '../../../../../environments/environment';
@Component({
  selector: 'app-modulecreation',
  standalone: true,
  imports: [InputComponent, ButtonComponent, CommonModule],
  templateUrl: './modulecreation.component.html',
  styleUrl: './modulecreation.component.scss'
})
export class ModulecreationComponent implements OnInit {
  cTitle: string = '';
  cImage: string = '';
  permission: string = 'N';

  helpcenterURL = `${environment.documentStorage}${environment.helpcenterPath}help/`;
  
  constructor(private dialogRef: MatDialogRef<ModulecreationComponent>, private helpS: HelpcenterService, private toast: TostbarService, private cdr: ChangeDetectorRef) { }

  ngOnInit(): void {
  }

  async onSubmit() {
    // console.log(this.cFolder);
    const data = {
      cTitle: this.cTitle,
      cPermission: "I",
      cImage: this.cImage,
      nMainid: null
    }
    const res  = await this.helpS.module_iu(data);
    if(res.msg == 1){
    this.dialogRef.close(true);
    }
    else {
      this.toast.error(res.value);
    }


  }

  close() {
    this.dialogRef.close();
  }

  getFile() {
    const fileInput: any = document.querySelector('#moduleimage');
    fileInput.click();
  }

  async onFileChange(e) {
    if (!e.target.files[0]) return;
    const formData = new FormData();
    formData.append('rootPath', 'help');
    formData.append('file', e.target.files[0]);
    const res = await this.helpS.moduleimageUpload(formData);
    console.log('onFileChange', res);
    if (res?.msg == 1) {
      this.cImage = res.value;
    }
    this.cdr.detectChanges();
  }
  
  
  
}
