import { Component, ViewChild } from '@angular/core';
import { ModuleslistComponent } from '../moduleslist/moduleslist.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { ModuleformComponent } from '../moduleform/moduleform.component';
import { HelpcenterService } from '../../../../shared/services/helpcenter/helpcenter.service';
@Component({
  selector: 'app-helpcenteradmin',
  standalone: true,
  imports: [ModuleslistComponent, IconComponent, EmptyComponent, ModuleformComponent],
  templateUrl: './helpcenteradmin.component.html',
  styleUrl: './helpcenteradmin.component.scss'
})
export class HelpcenteradminComponent {

  @ViewChild('moduleslist') moduleslist!: ModuleslistComponent;
  selectedmodule: any;
  curruntmodule: any;
  addform: boolean = false;
  constructor(private helpcenterService: HelpcenterService) {
  }

  selectedmoduleEvent(event: any) {
    debugger;
    if (event.type == 'SelectedModule') {
      this.selectedmodule = event.data.nSMid;
      this.curruntmodule = event.data.nMainid;
    }

    if (event.type == 'AddForm') {
      debugger;
      this.selectedmodule = null;
      this.addform = true;
      this.curruntmodule = event.data;
    }

  }

  moduleupdated(event: any) {
    if (this.moduleslist) {
      this.moduleslist.deselectmodule();
    }
    debugger;
    this.selectedmodule = null;
    this.addform = false;
    this.curruntmodule = null;
  }


}
