import { Component, EventEmitter, Output } from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { NgClass } from '@angular/common';
import { HelpcenterService } from '../../../../shared/services/helpcenter/helpcenter.service';
import { ModulecreationComponent } from '../modulecreation/modulecreation.component';
import { MatDialog } from '@angular/material/dialog';
@Component({
  selector: 'moduleslist',
  standalone: true,
  imports: [IconComponent, ButtonComponent, NgClass],
  templateUrl: './moduleslist.component.html',
  styleUrl: './moduleslist.component.scss'
})
export class ModuleslistComponent {
  modules: any[] = [];
  @Output() selectedmodule: EventEmitter<any> = new EventEmitter();

  constructor(private helpcenterService: HelpcenterService, private matdialog: MatDialog) {
  }

  toggleModule(module: any, index: number) {
    module.isExpanded = !module.isExpanded;
  }

  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.getmodules();
  }

  getmodules() {
    debugger;
    this.helpcenterService.getModuleList().then((res: any) => {
      this.modules = res;
      this.modules.forEach((module, index) => {
        this.getsubmodules(module.nMainid, index);
      });
    });
  }

  getsubmodules(nMainid: string, index: number) {
    this.helpcenterService.getSubModuleList(nMainid).then((res: any) => {
      debugger;
      console.log(res);
      this.modules[index].submodules = res;
    });
  }


  selectmodule(submodule: any, module: any) {
    debugger;
    this.selectedmodule.emit({ type: 'SelectedModule', data: { nSMid: submodule.nSMid, nMainid: module.nMainid } });
    this.modules.forEach((module) => {
      module.submodules.forEach((submodule) => {
        submodule.isselected = false;
      });
    });
    submodule.isselected = true;
  }

  addsubmodule(module: any) {
    debugger;
    this.selectedmodule.emit({ type: 'AddForm', data: module.nMainid });
  }

  //openmatdialog


  createModule() {
    const dialogRef = this.matdialog.open(ModulecreationComponent, {
      width: '500px',
      height: 'fit-content',
    });
    dialogRef.afterClosed().subscribe((result) => {
      if (result) {
        this.getmodules();
      }
    });
  }


  deselectmodule() {
    this.modules.forEach((module) => {
      module.submodules.forEach((submodule) => {
        submodule.isselected = false;
      });
    });
    this.getmodules();
  }
}
